import { describe, it, expect } from "vitest";
import { compress, decompress } from "./compression";

describe("compression", () => {
  it("round-trips compressible data", async () => {
    const encoder = new TextEncoder();
    const original = encoder.encode("hello world ".repeat(100));
    const { data: compressed, compressed: didCompress } = await compress(original);
    expect(didCompress).toBe(true);
    expect(compressed.length).toBeLessThan(original.length);

    const decompressed = await decompress(compressed);
    expect(decompressed).toEqual(original);
  });

  it("skips compression below threshold", async () => {
    const encoder = new TextEncoder();
    const original = encoder.encode("small");
    const { data, compressed } = await compress(original);
    expect(compressed).toBe(false);
    expect(data).toEqual(original);
  });

  it("decompresses Go-generated fixture", async () => {
    // Hex of gzip-compressed "cross-language gzip fixture for binary wire protocol testing " x20
    // Generated by Go gateway/compression_test.go TestCrossLanguageFixture.
    const fixtureHex =
      "1f8b08000000000000ffeccbdd09c0200c04e0556e810e65258680183923fd99be63f425037c95bed6d1cbd05d54a0af4d34bb6353d09c386d143eb88c82490fafde11b2c2862271e2c4897fc65f000000ffffa4f90a42c4040000";
    const fixture = hexToBytes(fixtureHex);

    const decompressed = await decompress(fixture);
    const decoder = new TextDecoder();
    const text = decoder.decode(decompressed);
    const expected = "cross-language gzip fixture for binary wire protocol testing ".repeat(20);
    expect(text).toBe(expected);
  });
});

function hexToBytes(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
  }
  return bytes;
}
